import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"H1 — Investigate a slow user journey","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/performance/01-investigate.md","filePath":"practice/frontend/performance/01-investigate.md"}'),i={name:"practice/frontend/performance/01-investigate.md"};function o(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="h1-—-investigate-a-slow-user-journey" tabindex="-1">H1 — Investigate a slow user journey <a class="header-anchor" href="#h1-—-investigate-a-slow-user-journey" aria-label="Permalink to “H1 — Investigate a slow user journey”">​</a></h1><p><strong>Learner status: outstanding.</strong> First required performance hometask. Prerequisites: a working public catalogue, <a href="./../../../frontend/performance/measurement.html">measurement</a> and <a href="./../../../frontend/performance/delivery.html">delivery</a>. Reuses E02/P-328/P-329.</p><h2 id="goal" tabindex="-1"><span class="hub-section-number">1 </span>Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “1 Goal”">​</a></h2><p>Turn “the app is slow” into a reproducible user action and an evidence-backed hypothesis. Do this before optimizing. The result is an investigation report, not a required Lighthouse score.</p><h2 id="work" tabindex="-1"><span class="hub-section-number">2 </span>Work <a class="header-anchor" href="#work" aria-label="Permalink to “2 Work”">​</a></h2><ol><li>Select an initial-load journey and an interaction journey in the same app: for example open <code>/courses</code>, then search/filter a deterministic large catalogue. State what the user expects to see and when the task is complete. Use public/generated data with a recorded size/seed.</li><li>Build and serve the production artifact using its documented commands. Record the revision, dependencies, browser/tool versions, viewport/DPR, CPU/network conditions, storage state and exact steps. Distinguish a physical device from desktop emulation.</li><li>Record at least three cold and three warm baseline trials for initial load. Define precisely which caches are cold/warm and how you reset them. Run the same interaction sequence at least three times, recording input feedback and eventual completion separately.</li><li>Save a Lighthouse report plus a Network waterfall and a Performance trace for representative runs. Retain raw values for every run. Explain median/range and any outlier rather than silently deleting it.</li><li>Identify the LCP candidate and its dependency chain. Inspect one real interaction&#39;s input, processing and presentation phases; inspect CLS during initial and delayed content. If nothing shifts, say what states were observed rather than claiming the whole app has zero CLS.</li><li>Rank up to three plausible causes by evidence, expected benefit, effort and correctness risk. Choose one loading and one interaction hypothesis for H2. If the fixture is already fast, use a disposable controlled variant, such as delaying a public hero or increasing the dataset; disclose the artificial setup.</li></ol><h2 id="required-report" tabindex="-1"><span class="hub-section-number">3 </span>Required report <a class="header-anchor" href="#required-report" aria-label="Permalink to “3 Required report”">​</a></h2><table tabindex="0"><thead><tr><th>Record</th><th>What to include</th></tr></thead><tbody><tr><td>Complaint and journey</td><td>Route, action, data, expected visible/usable result</td></tr><tr><td>Environment</td><td>Artifact, browser, viewport/DPR, CPU/network, cache reset procedure</td></tr><tr><td>Trials</td><td>Raw measurements, median/range, matching conditions</td></tr><tr><td>Causal evidence</td><td>Initiator chain / blocking task / layout work and screenshot or trace region</td></tr><tr><td>Hypotheses</td><td>Why this cause is plausible, how to falsify it and what change to test</td></tr><tr><td>Limits</td><td>No field pipeline, untested browsers/devices, observation scope</td></tr></tbody></table><p>A screenshot of a score is insufficient. A waterfall may show the hero starts after app JS and API work; a trace may show that the input event waits behind unrelated filtering. Explain how the evidence supports that interpretation and what would contradict it.</p><h2 id="failure-cases-to-investigate" tabindex="-1"><span class="hub-section-number">4 </span>Failure cases to investigate <a class="header-anchor" href="#failure-cases-to-investigate" aria-label="Permalink to “4 Failure cases to investigate”">​</a></h2><p>Delay/fail one image or font request; repeat with a warm cache; perform the interaction during loading. Observe whether the UI remains readable and whether feedback differs from completion. Restore the controlled fault after capture. Check a narrow viewport and keyboard operation of the chosen action.</p><h2 id="acceptance" tabindex="-1"><span class="hub-section-number">5 </span>Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to “5 Acceptance”">​</a></h2><p>Another person can follow the steps and encounter the same class of bottleneck. You can distinguish lab TBT from interaction latency/field INP, identify the actual LCP element and explain why request durations should not be summed into page-load time. No code optimization is necessary to complete H1, but the two H2 hypotheses must be concrete and testable.</p><p>Do not infer field p75 from local trials or treat an unused Coverage region as safe deletion across unrecorded states. Keep honest findings if evidence is inconclusive.</p><p>Next: <a href="./02-improve.html">H2 — Improve loading and interaction</a>.</p>',15)])])}const f=t(i,[["render",o]]);export{u as __pageData,f as default};
